const body = $input.first().json.body;
const required = ['employee_name', 'review_period', 'role', 'performance_notes'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (body.performance_notes.trim().length < 50) return [{ json: { valid: false, error: 'performance_notes too short — need at least 50 chars' } }];
const ratings = ['exceptional', 'exceeds_expectations', 'meets_expectations', 'below_expectations', 'unsatisfactory'];
const overallRating = ratings.includes(body.overall_rating) ? body.overall_rating : null;
const reviewTypes = ['annual', 'mid_year', 'quarterly', 'probation', '90_day', 'pip'];
const reviewType = reviewTypes.includes(body.review_type) ? body.review_type : 'annual';
return [{ json: {
  valid: true,
  employeeName: body.employee_name.trim(),
  employeeTitle: body.employee_title || body.role,
  role: body.role.trim(),
  department: body.department || '',
  reviewPeriod: body.review_period.trim(),
  reviewType,
  managerName: body.manager_name || '',
  performanceNotes: body.performance_notes.trim().slice(0, 4000),
  accomplishments: Array.isArray(body.accomplishments) ? body.accomplishments : (body.accomplishments || '').split('
').map(a=>a.trim()).filter(Boolean),
  areasForImprovement: Array.isArray(body.areas_for_improvement) ? body.areas_for_improvement : (body.areas_for_improvement || '').split('
').map(a=>a.trim()).filter(Boolean),
  goals: Array.isArray(body.goals_for_next_period) ? body.goals_for_next_period : (body.goals_for_next_period || '').split('
').map(g=>g.trim()).filter(Boolean),
  overallRating,
  competencies: body.competencies || [],
  tone: body.tone || 'constructive',
  wordTarget: parseInt(body.word_target) || 400,
  includeRatingsPerSection: body.include_section_ratings === true,
  replyEmail: body.reply_email || null,
  requestedAt: new Date().toISOString()
} }];

values.content:
Write a performance review.

Employee: {{ $json.employeeName }}
Title: {{ $json.employeeTitle }}
Role: {{ $json.role }}
Department: {{ $json.department || 'not specified' }}
Review period: {{ $json.reviewPeriod }}
Review type: {{ $json.reviewType.replace(/_/g,' ') }}
Manager: {{ $json.managerName || 'not specified' }}
Overall rating: {{ $json.overallRating ? $json.overallRating.replace(/_/g,' ') : 'not provided' }}
Target length: ~{{ $json.wordTarget }} words
Tone: {{ $json.tone }}
Include section ratings: {{ $json.includeRatingsPerSection }}
Competencies to cover: {{ $json.competencies.join(', ') || 'standard — infer from role' }}

Manager's raw notes:
{{ $json.performanceNotes }}

Key accomplishments listed:
{{ $json.accomplishments.map((a,i) => `${i+1}. ${a}`).join('\n') || 'see notes above' }}

Areas for development:
{{ $json.areasForImprovement.map((a,i) => `${i+1}. ${a}`).join('\n') || 'see notes above' }}

Goals for next period:
{{ $json.goals.map((g,i) => `${i+1}. ${g}`).join('\n') || 'see notes above' }}

Return this JSON:
{
  "overall_summary": "2-3 sentence opening that sets the overall tone and captures the essence of the review period",
  "sections": [
    {
      "title": "section name e.g. Performance & Accomplishments",
      "rating": "exceptional | exceeds | meets | below | unsatisfactory — null if not applicable",
      "content": "section narrative — specific, evidence-based, appropriate length for the section"
    }
  ],
  "strengths_highlighted": ["2-4 specific strengths called out in the review"],
  "development_areas": ["2-3 development areas with constructive framing"],
  "goals_next_period": [
    {
      "goal": "specific, measurable goal",
      "rationale": "why this goal matters for this employee's growth"
    }
  ],
  "closing_statement": "1-2 sentences wrapping up — forward-looking, appropriate to the rating",
  "full_review_text": "the complete review as a single formatted string ready to paste into an HR system — includes all sections with appropriate headers",
  "manager_notes": "1-2 internal notes for the manager before delivering this review — e.g. how to handle a sensitive topic, what to emphasize in the conversation"
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let review;
try { review = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
review._meta = { employeeName: input.employeeName, role: input.role, reviewPeriod: input.reviewPeriod, reviewType: input.reviewType, overallRating: input.overallRating, managerName: input.managerName, replyEmail: input.replyEmail };
return [{ json: review }];

const r = $input.first().json;
const m = r._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const ratingColors = { exceptional:'#16a34a', exceeds_expectations:'#2563eb', meets_expectations:'#6b7280', below_expectations:'#d97706', unsatisfactory:'#dc2626' };
const ratingLabels = { exceptional:'Exceptional', exceeds_expectations:'Exceeds Expectations', meets_expectations:'Meets Expectations', below_expectations:'Below Expectations', unsatisfactory:'Unsatisfactory' };
const rc = ratingColors[m.overallRating] || '#6b7280';
const rl = ratingLabels[m.overallRating] || m.overallRating || 'Not Rated';

const sectionBlocks = (r.sections||[]).map(s => {
  const sRatingLabel = s.rating ? (ratingLabels[s.rating.replace(/ /g,'_').toLowerCase()] || s.rating) : null;
  const sColor = s.rating ? (ratingColors[s.rating.replace(/ /g,'_').toLowerCase()] || '#6b7280') : null;
  return `<div style="margin-bottom:22px">
    <div style="display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #e5e7eb;padding-bottom:6px;margin-bottom:10px">
      <div style="font-size:14px;font-weight:700;text-transform:uppercase;letter-spacing:0.4px;color:#374151">${esc(s.title)}</div>
      ${sRatingLabel ? `<span style="background:${sColor}22;color:${sColor};font-size:11px;font-weight:700;padding:2px 10px;border-radius:10px">${esc(sRatingLabel)}</span>` : ''}
    </div>
    <div style="font-size:14px;line-height:1.8;color:#374151;white-space:pre-line">${esc(s.content)}</div>
  </div>`;
}).join('');

const goals = (r.goals_next_period||[]).map(g => `<div style="padding:9px 0;border-bottom:1px solid #f0f9ff">
  <div style="font-size:14px;font-weight:600;color:#1e40af">${esc(g.goal)}</div>
  <div style="font-size:13px;color:#6b7280;margin-top:3px">${esc(g.rationale)}</div>
</div>`).join('');

const strengths = (r.strengths_highlighted||[]).map(s => `<div style="font-size:14px;padding:5px 0;border-bottom:1px solid #f0fdf4;color:#166534">✓ ${esc(s)}</div>`).join('');
const devAreas = (r.development_areas||[]).map(d => `<div style="font-size:14px;padding:5px 0;border-bottom:1px solid #fff7ed;color:#78350f">→ ${esc(d)}</div>`).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f8f8f6;font-family:Georgia,'Times New Roman',serif;color:#1a1a1a">
<div style="max-width:720px;margin:0 auto">
  <div style="background:#1e293b;color:#fff;padding:22px 32px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#64748b;margin-bottom:5px">${esc(m.reviewType.replace(/_/g,' '))} Review · ${esc(m.reviewPeriod)}</div>
    <div style="font-size:20px;font-weight:700">${esc(m.employeeName)}</div>
    <div style="font-size:14px;color:#94a3b8;margin-top:4px">${esc(m.role)}${m.managerName ? ' · Manager: ' + esc(m.managerName) : ''}</div>
  </div>
  <div style="background:#fff;padding:14px 32px;border:1px solid #e5e7eb;border-top:none;display:flex;align-items:center;gap:14px">
    <span style="background:${rc};color:#fff;font-size:13px;font-weight:700;padding:5px 16px;border-radius:14px">${esc(rl)}</span>
    <p style="font-size:14px;line-height:1.7;color:#374151;margin:0">${esc(r.overall_summary)}</p>
  </div>
  <div style="background:#fff;padding:22px 32px;border:1px solid #e5e7eb;border-top:3px solid #f3f3f0;font-family:Georgia,serif">
    ${sectionBlocks}
    ${r.closing_statement ? `<p style="font-size:14px;line-height:1.8;color:#374151;font-style:italic;border-top:1px solid #e5e7eb;padding-top:16px;margin-top:8px">${esc(r.closing_statement)}</p>` : ''}
  </div>
  ${goals ? `<div style="background:#eff6ff;padding:16px 32px;border:1px solid #bfdbfe">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:8px">Goals for next period</div>
    ${goals}
  </div>` : ''}
  <div style="background:#fff;padding:14px 32px;border:1px solid #e5e7eb;border-top:3px solid #f3f3f0">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px">
      ${strengths ? `<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#15803d;margin-bottom:7px">Key strengths</div>${strengths}</div>` : ''}
      ${devAreas ? `<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#c2410c;margin-bottom:7px">Development areas</div>${devAreas}</div>` : ''}
    </div>
  </div>
  ${r.manager_notes ? `<div style="background:#fffbeb;padding:14px 32px;border:1px solid #fde68a">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#92400e;margin-bottom:5px">Manager notes (internal — don't share)</div>
    <div style="font-size:13px;color:#78350f;line-height:1.65">${esc(r.manager_notes)}</div>
  </div>` : ''}
  <div style="background:#1e293b;color:#475569;font-size:11px;padding:12px 32px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Performance Review · ${esc(m.employeeName)} · ${esc(m.reviewPeriod)}
  </div>
</div></body></html>`;

return [{ json: { html, replyEmail: m.replyEmail, employeeName: m.employeeName, reviewPeriod: m.reviewPeriod, overallRating: m.overallRating, review: r } }];
